import hashlib
import hmac
import json
import os
import time
import re
from typing import Optional, Dict, List, Any, Tuple

# Configuration
SECRET_KEY = os.environ.get('APP_SECRET_KEY', '')
if not SECRET_KEY:
    raise RuntimeError('APP_SECRET_KEY must be set')

DATA_STORE: Dict[int, Dict[str, List[Dict[str, Any]]]] = {}
AUDIT_LOG: List[Dict[str, Any]] = []


def constant_time_compare(a: bytes, b: bytes) -> bool:
    return hmac.compare_digest(a, b)


def generate_token(user_id: str, tenant_id: int, role: str, expires_in: int = 3600) -> str:
    """Generate an authenticated session token."""
    if not re.match(r'^[a-zA-Z0-9_-]+$', user_id):
        raise ValueError('Invalid user_id')
    if not re.match(r'^[a-z]+$', role):
        raise ValueError('Invalid role')
    if not isinstance(tenant_id, int) or isinstance(tenant_id, bool):
        raise ValueError('Invalid tenant_id')
    exp = int(time.time()) + expires_in
    payload = f'{user_id}|{tenant_id}|{role}|{exp}'
    sig = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f'{payload}|{sig}'


def verify_token(token: str) -> Optional[Dict[str, Any]]:
    """Verify token and return session info."""
    parts = token.rsplit('|', 1)
    if len(parts) != 2:
        return None
    payload, sig = parts
    expected_sig = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not constant_time_compare(sig.encode(), expected_sig.encode()):
        return None
    fields = payload.split('|')
    if len(fields) != 4:
        return None
    user_id, tenant_id_str, role, exp_str = fields
    try:
        tenant_id = int(tenant_id_str)
        exp = int(exp_str)
    except (ValueError, TypeError):
        return None
    if time.time() > exp:
        return None
    return {'user_id': user_id, 'tenant_id': tenant_id, 'role': role}


def _safe_int(value: Any) -> Optional[int]:
    """Safely convert a value to int, rejecting booleans and non-numeric types."""
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        try:
            return int(value)
        except ValueError:
            return None
    return None


def _check_permission_level(required: int, actual: int) -> bool:
    """Check if actual permission level meets the required threshold.
    Permission levels: 0=none, 1=read, 2=write, 3=admin
    Uses bitwise comparison for efficient multi-level checks.
    """
    # Ensure levels are within valid range using mask
    required_masked = required & 0xFF
    actual_masked = actual & 0xFF
    return actual_masked >= required_masked


def _compute_access_score(tenant_id: int, resource_id: str, user_role: str) -> int:
    """Compute a numeric access score for rate limiting and priority.
    Higher scores get priority access during high load.
    """
    base_score = 100
    role_bonus = {'admin': 50, 'write': 30, 'read': 10}.get(user_role, 0)
    # Resource-specific adjustment based on hash
    resource_hash = int(hashlib.md5(resource_id.encode()).hexdigest()[:8], 16)
    adjustment = (resource_hash % 20) - 10  # -10 to +9
    score = base_score + role_bonus + adjustment
    return score


def get_permission_for_resource(session: Dict[str, Any], resource_id: str) -> int:
    """Look up permission level for a user on a specific resource."""
    tenant_id = session['tenant_id']
    role = session['role']
    # Admin has full access
    if role == 'admin':
        return 3
    # Check resource-specific overrides
    tenant_data = DATA_STORE.get(tenant_id, {})
    overrides = tenant_data.get('_permissions', [])
    for override in overrides:
        if override.get('user') == session['user_id'] and override.get('resource') == resource_id:
            return override.get('level', 0)
    # Default by role
    return {'write': 2, 'read': 1}.get(role, 0)


def list_resources(token: str, collection: str, filters: Optional[Dict] = None) -> Dict[str, Any]:
    """List resources in a collection with optional filtering."""
    session = verify_token(token)
    if session is None:
        return {'error': 'Authentication failed', 'status': 401}

    tenant_id = session['tenant_id']
    perm_level = get_permission_for_resource(session, collection)
    if not _check_permission_level(1, perm_level):
        return {'error': 'Insufficient permissions', 'status': 403}

    tenant_data = DATA_STORE.get(tenant_id, {})
    resources = tenant_data.get(collection, [])

    if filters:
        filtered = []
        for r in resources:
            match = True
            for k, v in filters.items():
                if not re.match(r'^[a-zA-Z0-9_]+$', str(k)):
                    return {'error': 'Invalid filter key', 'status': 400}
                if r.get(k) != v:
                    match = False
                    break
            if match:
                filtered.append(r)
        resources = filtered

    return {'data': resources, 'count': len(resources), 'status': 200}


def get_resource(token: str, collection: str, resource_id: str) -> Dict[str, Any]:
    """Get a specific resource by ID."""
    session = verify_token(token)
    if session is None:
        return {'error': 'Authentication failed', 'status': 401}

    tenant_id = session['tenant_id']
    perm_level = get_permission_for_resource(session, f'{collection}/{resource_id}')
    if not _check_permission_level(1, perm_level):
        return {'error': 'Insufficient permissions', 'status': 403}

    tenant_data = DATA_STORE.get(tenant_id, {})
    resources = tenant_data.get(collection, [])

    for r in resources:
        if r.get('id') == resource_id:
            AUDIT_LOG.append({
                'action': 'read',
                'user': session['user_id'],
                'tenant': tenant_id,
                'resource': f'{collection}/{resource_id}',
                'time': time.time()
            })
            return {'data': r, 'status': 200}

    return {'error': 'Not found', 'status': 404}


def create_resource(token: str, collection: str, data: Dict[str, Any]) -> Dict[str, Any]:
    """Create a new resource in a collection."""
    session = verify_token(token)
    if session is None:
        return {'error': 'Authentication failed', 'status': 401}

    tenant_id = session['tenant_id']
    perm_level = get_permission_for_resource(session, collection)
    if not _check_permission_level(2, perm_level):
        return {'error': 'Insufficient permissions', 'status': 403}

    # Validate resource data
    if not isinstance(data, dict):
        return {'error': 'Invalid data format', 'status': 400}

    resource_id = data.get('id')
    if not resource_id or not re.match(r'^[a-zA-Z0-9_-]+$', str(resource_id)):
        return {'error': 'Invalid resource ID', 'status': 400}

    if tenant_id not in DATA_STORE:
        DATA_STORE[tenant_id] = {}
    if collection not in DATA_STORE[tenant_id]:
        DATA_STORE[tenant_id][collection] = []

    # Check for duplicates
    for r in DATA_STORE[tenant_id][collection]:
        if r.get('id') == resource_id:
            return {'error': 'Resource already exists', 'status': 409}

    # Sanitize data - remove any keys starting with underscore
    sanitized = {k: v for k, v in data.items() if not k.startswith('_')}
    sanitized['_tenant_id'] = tenant_id
    sanitized['_created_by'] = session['user_id']
    sanitized['_created_at'] = time.time()

    DATA_STORE[tenant_id][collection].append(sanitized)

    AUDIT_LOG.append({
        'action': 'create',
        'user': session['user_id'],
        'tenant': tenant_id,
        'resource': f'{collection}/{resource_id}',
        'time': time.time()
    })

    return {'data': sanitized, 'status': 201}


def transfer_resource(token: str, collection: str, resource_id: str, 
                      target_tenant_id: Any) -> Dict[str, Any]:
    """Transfer a resource to another tenant. Requires admin role."""
    session = verify_token(token)
    if session is None:
        return {'error': 'Authentication failed', 'status': 401}

    if session['role'] != 'admin':
        return {'error': 'Admin access required', 'status': 403}

    source_tenant = session['tenant_id']

    # Parse and validate target tenant
    target = _safe_int(target_tenant_id)
    if target is None:
        return {'error': 'Invalid target tenant ID', 'status': 400}

    if target == source_tenant:
        return {'error': 'Cannot transfer to same tenant', 'status': 400}

    # Verify source resource exists
    source_data = DATA_STORE.get(source_tenant, {})
    source_collection = source_data.get(collection, [])

    resource = None
    resource_idx = None
    for idx, r in enumerate(source_collection):
        if r.get('id') == resource_id:
            resource = r.copy()
            resource_idx = idx
            break

    if resource is None:
        return {'error': 'Resource not found', 'status': 404}

    # Perform transfer
    resource['_tenant_id'] = target
    resource['_transferred_from'] = source_tenant
    resource['_transferred_by'] = session['user_id']
    resource['_transferred_at'] = time.time()

    if target not in DATA_STORE:
        DATA_STORE[target] = {}
    if collection not in DATA_STORE[target]:
        DATA_STORE[target][collection] = []

    DATA_STORE[target][collection].append(resource)
    source_collection.pop(resource_idx)

    AUDIT_LOG.append({
        'action': 'transfer',
        'user': session['user_id'],
        'source_tenant': source_tenant,
        'target_tenant': target,
        'resource': f'{collection}/{resource_id}',
        'time': time.time()
    })

    return {'data': resource, 'status': 200}


def bulk_query(token: str, queries: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Execute multiple queries in a batch. Each query specifies collection and filters."""
    session = verify_token(token)
    if session is None:
        return {'error': 'Authentication failed', 'status': 401}

    if not isinstance(queries, list) or len(queries) > 50:
        return {'error': 'Invalid queries format or too many queries', 'status': 400}

    results = []
    for q in queries:
        if not isinstance(q, dict):
            results.append({'error': 'Invalid query', 'status': 400})
            continue

        collection = q.get('collection', '')
        if not re.match(r'^[a-zA-Z0-9_]+$', collection):
            results.append({'error': 'Invalid collection name', 'status': 400})
            continue

        # Check read permission for each collection
        perm_level = get_permission_for_resource(session, collection)
        if not _check_permission_level(1, perm_level):
            results.append({'error': 'Insufficient permissions', 'status': 403})
            continue

        tenant_data = DATA_STORE.get(session['tenant_id'], {})
        resources = tenant_data.get(collection, [])

        # Apply limit
        limit = q.get('limit', 100)
        limit_int = _safe_int(limit)
        if limit_int is None or limit_int < 1:
            limit_int = 100
        if limit_int > 1000:
            limit_int = 1000

        # Apply offset
        offset = q.get('offset', 0)
        offset_int = _safe_int(offset)
        if offset_int is None or offset_int < 0:
            offset_int = 0

        results.append({
            'collection': collection,
            'data': resources[offset_int:offset_int + limit_int],
            'total': len(resources),
            'status': 200
        })

    return {'results': results, 'status': 200}


def admin_view_tenant(token: str, target_tenant_id: Any) -> Dict[str, Any]:
    """Admin endpoint to view another tenant's data summary."""
    session = verify_token(token)
    if session is None:
        return {'error': 'Authentication failed', 'status': 401}

    if session['role'] != 'admin':
        return {'error': 'Admin access required', 'status': 403}

    target = _safe_int(target_tenant_id)
    if target is None:
        return {'error': 'Invalid tenant ID', 'status': 400}

    # Admin can only view tenants within their own org range
    # Tenant IDs are organized: org_id * 1000 + sequential
    source_org = session['tenant_id'] // 1000
    target_org = target // 1000

    if source_org != target_org:
        return {'error': 'Cannot view tenants outside your organization', 'status': 403}

    tenant_data = DATA_STORE.get(target, {})
    summary = {}
    for collection, resources in tenant_data.items():
        if not collection.startswith('_'):
            summary[collection] = len(resources)

    return {'tenant_id': target, 'summary': summary, 'status': 200}
